#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

struct List {
    int *items;
    size_t used;
    size_t capacity;
};

static int resize(struct List *list, size_t requested, int allowed)
{
    if (requested == 0 || requested < list->used ||
        requested > SIZE_MAX / sizeof *list->items) {
        return -1;
    }
    if (requested == list->capacity) {
        return 1;
    }
    if (!allowed) {
        return 0;
    }
    int *next = realloc(list->items, requested * sizeof *list->items);
    if (next == NULL) {
        return 0;
    }
    list->items = next;
    list->capacity = requested;
    return 1;
}

int main(void)
{
    if (2 > SIZE_MAX / sizeof(int)) {
        puts("size-error");
        return 0;
    }
    struct List list = {malloc(2 * sizeof(int)), 2, 2};
    if (list.items == NULL) {
        puts("allocation-failed");
        return 0;
    }
    list.items[0] = 8;
    list.items[1] = 13;
    int result = resize(&list, 4, 1);
    const char *status = result == 1 ? "ok" : (result == 0 ? "allocation-failed" : "invalid");
    printf("%s %zu %d\n", status, list.capacity, list.items[0] + list.items[1]);
    free(list.items);
    return 0;
}

